#include "common.hpp"
#include "cache_disk.hpp"
#include <filesystem>
using namespace fsizes;
bool query(const std::wstring& path,Response& r){Request q;q.characters=uint32_t(path.size());std::vector<BYTE>d(sizeof(q)+path.size()*2);memcpy(d.data(),&q,sizeof(q));memcpy(d.data()+sizeof(q),path.data(),path.size()*2);DWORD n=0;return CallNamedPipeW(sessionPipe().c_str(),d.data(),DWORD(d.size()),&r,sizeof(r),&n,1000)&&n==sizeof(r);}
HANDLE launch(const wchar_t* args){auto exe=directory()+L"\\bin\\WindowsFolderSize.exe";auto command=L"\""+exe+L"\" "+args;STARTUPINFOW si{sizeof(si)};PROCESS_INFORMATION pi{};if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&si,&pi))return nullptr;CloseHandle(pi.hThread);return pi.hProcess;}
void stop(HANDLE broker){HANDLE p=launch(L"--stop");if(p){WaitForSingleObject(p,3000);CloseHandle(p);}WaitForSingleObject(broker,5000);CloseHandle(broker);}
int wmain(){SetEnvironmentVariableW(L"FOLDERSIZE_TEST",L"1");auto root=directory()+L"\\persist-fixture-"+std::to_wstring(GetCurrentProcessId());std::filesystem::create_directory(root);auto file=root+L"\\file.bin";auto write=[&](unsigned bytes){HANDLE h=CreateFileW(file.c_str(),GENERIC_WRITE,FILE_SHARE_READ,nullptr,CREATE_ALWAYS,0,nullptr);std::vector<char>d(bytes);DWORD n;WriteFile(h,d.data(),bytes,&n,nullptr);CloseHandle(h);};write(42);HANDLE broker=launch(L"");if(!broker)return 2;Response r;bool ready=false;for(int i=0;i<100;i++){if(query(root,r)&&r.ready&&r.bytes==42){ready=true;break;}Sleep(100);}if(!ready){stop(broker);return 3;}stop(broker);auto saved=loadSizes(dataDirectory()+L"\\folder-sizes.cache");if(saved.find(root)==saved.end()){ // broker normalizes paths
 CharLowerBuffW(root.data(),DWORD(root.size()));if(saved.find(root)==saved.end())return 4;}
 write(99);broker=launch(L"");bool restored=false;for(int i=0;i<100;i++){if(query(root,r)){restored=r.ready&&r.bytes==42;break;}Sleep(50);}if(!restored){stop(broker);return 5;}ready=false;for(int i=0;i<100;i++){if(query(root,r)&&r.ready&&r.bytes==99){ready=true;break;}Sleep(100);}stop(broker);std::filesystem::remove(file);std::filesystem::remove(root);if(!ready)return 6;puts("PASS persistent cache: disk save, process restart, first response restores 42 bytes, offline edit refreshes to 99 bytes");return 0;}
